#!/usr/bin/env bash
# wake-cursor.sh — start a headless cursor-agent turn for one handoff.
# Generated by `install.sh --target cursor`.
#
#   wake-cursor.sh "<handoff>"            # a fresh headless turn
#   wake-cursor.sh "<handoff>" <sid>      # resume session <sid>
#
# Both forms are Cursor's documented surface: `-p/--print` (headless),
# `--resume [chatId]` and `--continue`. `scripts/verify/host-resume-matrix.mjs
# --host cursor --e2e` probes them against the real CLI when CURSOR_API_KEY is
# set; without that key the probe SKIPs. If your build differs, point the
# supervisor's `--wake-command` at your own glue.
#
# A worker must run in the card's project directory, and only this host-local
# glue can resolve it. Inputs (set by the supervisor):
#   TP_PROJECT        the card's board project identity
#   TP_PROJECTS_JSON  the local project map (default: beside the installed skill)
#   TP_NODE           node used to resolve it (default: `node` on PATH)
# If the directory cannot be resolved, exit 3 without starting a worker.
set -eu

prompt="${1:-}"
sid="${2:-}"

if [ -z "$prompt" ]; then
  echo "wake-cursor: a handoff prompt is required" >&2
  exit 2
fi

projects_json="${TP_PROJECTS_JSON:-$(dirname "$0")/../skills/meerkat-taskpanel/projects.json}"
if ! cwd="$("${TP_NODE:-node}" "{{LOOP}}/scripts/wake-cwd.mjs" --project "${TP_PROJECT:-}" --projects-json "$projects_json")"; then
  echo "wake-cursor: refusing to wake a worker without a target directory" >&2
  exit 3
fi
# `if !` cannot catch an empty $cwd: `cd ""` succeeds in bash and would run the
# worker in the caller's directory. The absolute-path test covers empty and relative.
case "$cwd" in
  /*) ;;
  *) echo "wake-cursor: refusing to wake a worker without a target directory" >&2; exit 3 ;;
esac
cd "$cwd"
echo "wake-cursor: working directory $cwd" >&2

# Full tool access is an opt-in of the *resident* session pool (`--session`),
# where the operator records an authorization in the host config. This legacy
# one-shot glue stays inside the no-default-bypass rule: it never adds one.
if [ -n "$sid" ]; then
  exec cursor-agent -p --resume "$sid" "$prompt"
fi

exec cursor-agent -p "$prompt"
